"use client"
import { PageHeader } from "@/components/PageHeader"
import { useState, useMemo, useEffect } from "react"
import Link from "next/link"
import { Users, Building2, CalendarDays, ClipboardList } from "lucide-react"
import { getDefaultAcademicYearClient } from "@/lib/academicYear"

export function TeacherClassesClient({ initialClasses, academicYears }: { initialClasses?: any[], academicYears?: any[] }) {
  const safeYears = useMemo(() => Array.isArray(academicYears) ? academicYears : [], [academicYears])
  const safeClasses = useMemo(() => Array.isArray(initialClasses) ? initialClasses.filter(Boolean) : [], [initialClasses])

  const [selectedYearId, setSelectedYearId] = useState(() => getDefaultAcademicYearClient(safeYears)?.id || "")

  useEffect(() => {
    if (typeof window !== "undefined") {
      const stored = localStorage.getItem("selectedAcademicYear")
      if (stored && safeYears.some(y => y && y.id === stored)) {
        setSelectedYearId(stored)
      }
    }
  }, [safeYears])

  const filteredClasses = useMemo(() => {
    if (!selectedYearId) return safeClasses
    return safeClasses.filter(c => c && c.academicYearId === selectedYearId)
  }, [safeClasses, selectedYearId])

  return (
    <div className="space-y-6">
      {/* Header Bar */}
      <PageHeader
        title="Lớp học của tôi"
        description="Quản lý các lớp học được phân công và xem kết quả khảo sát"
        breadcrumbs={[
          { label: "Công tác Giảng dạy", href: "/teacher" },
          { label: "Lớp học" }
        ]}
        actions={
          <div className="flex items-center gap-1.5 bg-white px-3 py-1.5 rounded-xl border border-slate-200 text-xs font-semibold">
            <CalendarDays className="w-3.5 h-3.5 text-slate-400" />
            <select 
              value={selectedYearId} 
              onChange={e => {
                setSelectedYearId(e.target.value)
                if (typeof window !== "undefined") {
                  localStorage.setItem("selectedAcademicYear", e.target.value)
                  document.cookie = "selectedAcademicYear=" + e.target.value + "; path=/; max-age=31536000; SameSite=Lax"
                }
              }} 
              className="bg-transparent text-xs font-bold text-slate-700 outline-none cursor-pointer max-w-[140px] sm:max-w-none"
            >
              {safeYears.filter(ay => ay && !ay.isOff).map(ay => (
                <option key={ay.id} value={ay.id}>Năm học {ay.name}</option>
              ))}
            </select>
          </div>
        }
      />

      {/* Classes Grid */}
      {filteredClasses.length === 0 ? (
        <div className="bg-white rounded-xl shadow-sm p-16 text-center border-2 border-teal-100">
          <ClipboardList className="w-12 h-12 text-slate-300 mx-auto mb-4" />
          <h3 className="text-base font-bold text-slate-800">Không có lớp học nào</h3>
          <p className="text-slate-400 text-sm mt-1">Bạn chưa được phân công lớp học nào trong năm học này.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
          {filteredClasses.map((c) => (
            <div key={c.id} className="bg-white rounded-2xl shadow-sm border-2 border-teal-100 overflow-hidden hover:shadow-md hover:border-[#48BFE3]/30 transition-all group flex flex-col justify-between">
              <div className="p-6">
                <div className="flex justify-between items-start mb-4">
                  <div>
                    <h3 className="font-extrabold text-lg text-slate-800 group-hover:text-[#48BFE3] transition-colors">{c.className}</h3>
                    <p className="text-xs font-bold text-[#48BFE3] mt-0.5">{c.classCode}</p>
                  </div>
                  <div className="flex flex-col items-end gap-1.5">
                    {c.isHomeroom && (
                      <span className="text-[9px] font-black tracking-wider px-2 py-0.5 rounded-full uppercase bg-[#48BFE3] text-white border border-[#48BFE3]">
                        Lớp chủ nhiệm
                      </span>
                    )}
                    <span className={`text-[10px] font-black tracking-wider px-2.5 py-1 rounded-full uppercase ${c.status === "ACTIVE" ? "bg-teal-50 text-[#48BFE3] border border-teal-100" : "bg-slate-100 text-slate-500"}`}>
                      {c.status}
                    </span>
                  </div>
                </div>
                
                <div className="space-y-3 mt-6">
                  <div className="flex items-center text-xs font-semibold text-slate-500">
                    <Building2 className="w-4 h-4 mr-2 text-slate-400" />
                    Cơ sở: <span className="text-slate-700 ml-1 font-bold">{c.campus?.campusName || 'N/A'}</span>
                  </div>
                  <div className="flex items-center text-xs font-semibold text-slate-500">
                    <CalendarDays className="w-4 h-4 mr-2 text-slate-400" />
                    Năm học: <span className="text-slate-700 ml-1 font-bold">{c.academicYear?.name || 'N/A'}</span>
                  </div>
                  <div className="flex items-center text-xs font-semibold text-slate-500">
                    <Users className="w-4 h-4 mr-2 text-slate-400" />
                    Học sinh: <span className="text-slate-700 ml-1 font-bold">{c._count?.students || 0} học sinh</span>
                  </div>
                </div>
              </div>
              
              <div className="flex justify-end text-xs font-semibold p-6 pt-0">
                <Link 
                  href={`/teacher/classes/${c.id}`} 
                  className="text-xs font-bold text-[#48BFE3] hover:text-[#009085] transition-colors flex items-center gap-1.5"
                >
                  {c.isHomeroom ? "Xem chi tiết Lớp chủ nhiệm →" : "Xem chi tiết kết quả khảo sát →"}
                </Link>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}
